const Z_AXIS = { origin: { x: 0, y: 0, z: 0 }, dir: { x: 0, y: 0, z: 1 } }

/** WO UI-5-R2: sentinel thrown by paintPreviewBodyGuarded's tessellate
 *  wrapper the instant it detects the push/pull generation has moved on
 *  (cancel/commit fired) -- aborts progressiveTessellate BEFORE its next
 *  cache.ingest/onPaint runs. Never inspected by value (the catch decides by
 *  re-reading the generation), it exists only to unwind the in-flight
 *  progressive pass without painting.
 *  WO UI-14A (BK-87 fold-in, UI-5.audit.json note finding): this is a
 *  MODULE-LEVEL SINGLETON, not allocated per preview frame -- deliberate
 *  (zero allocation on a hot progressive-tessellation path), but its `stack`
 *  is therefore captured once at module init, not at the aborted paint's own
 *  call site; never log/inspect .stack off this value. If a future change
 *  needs to distinguish this sentinel from a genuine same-shaped Error,
 *  compare by identity (`err === STALE_PREVIEW_PAINT`), never by message/
 *  stack -- correctness here never depends on that today (the catch decides
 *  purely by re-reading the generation). */


type MeshPair = BodyPresentationPair

interface BodyInteractionPresentation {
  key: string
  object: THREE.Object3D
}

const RESTING_SELECTION = new SelectionState()

function bodyColorToHex(color: RGB): string {
  const channel = (value: number): string =>
    Math.round(Math.max(0, Math.min(1, value)) * 255).toString(16).padStart(2, '0')
  return `#${channel(color[0])}${channel(color[1])}${channel(color[2])}`
}

function bodyColorFromHex(color: string | undefined): RGB | undefined {
  if (color === undefined || !/^#[0-9a-f]{6}$/i.test(color)) return undefined
  const packed = Number.parseInt(color.slice(1), 16)
  return [
    ((packed >> 16) & 0xff) / 255,
    ((packed >> 8) & 0xff) / 255,
    (packed & 0xff) / 255,
  ]
}

/** GEO-18: recover the picked face's real world-space frame from the same
 *  painted mesh/ray path Push/Pull and Hole already use. No +Z fallback:
 *  callers can surface an unavailable/degenerate frame honestly. */
function draftFaceFrameFromMesh(meshPair: MeshPair | undefined, ray: RayLike, origin: Vec3): DraftFaceFrame | undefined {
  if (meshPair === undefined) return undefined
  const raycaster = new THREE.Raycaster()
  raycaster.set(
    new THREE.Vector3(ray.origin.x, ray.origin.y, ray.origin.z),
    new THREE.Vector3(ray.direction.x, ray.direction.y, ray.direction.z).normalize(),
  )
  const [intersection] = raycaster.intersectObject(meshPair.mesh, false)
  const localNormal = intersection?.face?.normal
  if (localNormal === undefined) return undefined
  const worldNormal = localNormal.clone().transformDirection(meshPair.mesh.matrixWorld).normalize()
  const frame: DraftFaceFrame = {
    origin: { x: origin.x, y: origin.y, z: origin.z },
    normal: { x: worldNormal.x, y: worldNormal.y, z: worldNormal.z },
  }
  const resolved = draftFaceNormalPlane(frame, false, 0)
  return resolved.ok ? frame : undefined
}

/** The ambient roots are also the synchronous ownership token for the
 *  base-plane pick transaction. React state schedules the visible mode, but
 *  already-queued DOM callbacks must be able to refuse immediately after an
 *  exit, before the next render installs fresh closures. Keeping that token
 *  on the canonical ambient-root map gives the picker one long-lived owner
 *  without introducing a second mode store. */
type AmbientGenesisGlyphMap = Map<string, THREE.Object3D> & { basePlanePickActive: boolean }

function createAmbientGenesisGlyphMap(): AmbientGenesisGlyphMap {
  return Object.assign(new Map<string, THREE.Object3D>(), { basePlanePickActive: false })
}

function basePlanePickReadout(nodeId: string): string {
  const kind = BASE_PLANE_BY_NODE_ID[nodeId]
  return kind === undefined ? workbenchText('SolidsWorkbenchPage.unknownBasePlane') : workbenchText('SolidsWorkbenchPage.plane3', { value1: String(BASE_PLANE_LABELS[kind]) })
}

/** WO SKC-5: this page's sketch interaction state -- distinct from
 *  `DialogState` (a modal) because plane/face targeting is an in-viewport
 *  click-to-pick interaction, never a dialog. Fresh face entry belongs to
 *  the unified 'pick-base-plane' mode; 'pick-face' remains only for Q5's
 *  minimal reattach and re-points an EXISTING degraded datum.
 *
 *  WO SKC-15C (THE SEVERING): the 'editing' kind is GONE. It was the old inline sketch3d draw
 *  machine (stepDrawTool/pickGrabTarget, a select+line+circle+arc toolbar of this page's own) that
 *  Operator rejected in T-SKC-PARITY. SKC-15B mounted THE Sketcher package alongside it for
 *  free-sketch entry; this WO routes sketch-on-face and sketch RE-ENTRY through the same mount and
 *  deletes the inline machine outright. There is now exactly ONE sketch draw machine reachable
 *  from this page, and no file in which a second one could be written -- which is the property
 *  src/tests/model3d/oneWorkbenchSketchPointerOwner.test.ts asserts. */
type SketchMode =
  | { kind: 'none' }
  | { kind: 'pick-base-plane' }
  | { kind: 'pick-face'; forDatumId: string }
  /**
   * THE MOUNT: a live session of the self-contained Sketcher package (src/lib/sketch/sketcher/**)
   * on a plane. `planeNodeId` is a base-plane genesis node (free sketch) or a face-plane datum
   * (sketch on face) -- the session does not care which, because a plane is a `PlaneFrame` and
   * both kinds of node resolve to one.
   */
  | { kind: 'package'; sketchNodeId: string; planeNodeId: string }

/** Half-extent (mm) the normal-to-plane camera framing falls back to when the sketch has no
 *  geometry to size itself off -- a fresh base-plane sketch. Matches `genesisGlyphs.PLANE_HALF_MM`,
 *  so entering a sketch on XY frames exactly the plane glyph the tree row already showed. */
const DEFAULT_SKETCH_SIZE_HINT_MM = 40

/** WO UI-17 (criterion 8): the sketch-plane grid's side length -- "sized
 *  sensibly to the view": generously past the session's own size hint (the
 *  normal-to-plane framing radius) with a floor comfortably beyond the base
 *  plane glyph, so the grid always reads as the working plane rather than a
 *  postage stamp under the geometry. */
function sketchGridSizeMm(sizeHintMm: number | undefined): number {
  return Math.max(200, (sizeHintMm ?? DEFAULT_SKETCH_SIZE_HINT_MM) * 5)
}

/** Read-only framing measurement for a picked face. It reads face triangles rather than boundary
 * extraction, so fresh entry cannot trigger a legacy projection refusal merely to size the view. */
function faceSketchSizeHintMm(body: CachedBody, faceId: string, frame: PlaneFrame): number {
  const positions = body.geometry.getAttribute('position')
  const index = body.geometry.getIndex()
  if (positions === undefined || index === null) return DEFAULT_SKETCH_SIZE_HINT_MM

  let radiusMm = 0
  let found = false
  for (let triangle = 0; triangle < body.triFace.length; triangle++) {
    if (body.faceIds[body.triFace[triangle]] !== faceId) continue
    for (let corner = 0; corner < 3; corner++) {
      const vertex = index.getX(triangle * 3 + corner)
      const point = { x: positions.getX(vertex), y: positions.getY(vertex), z: positions.getZ(vertex) }
      if (![point.x, point.y, point.z].every(Number.isFinite)) return DEFAULT_SKETCH_SIZE_HINT_MM
      const local = worldToLocal(frame, point)
      if (![local.x, local.y].every(Number.isFinite)) return DEFAULT_SKETCH_SIZE_HINT_MM
      radiusMm = Math.max(radiusMm, Math.hypot(local.x, local.y))
      found = true
    }
  }
  return found && Number.isFinite(radiusMm)
    ? Math.max(DEFAULT_SKETCH_SIZE_HINT_MM / 4, radiusMm)
    : DEFAULT_SKETCH_SIZE_HINT_MM
}

/**
 * WO SKC-15C: the argument of `beginPackageSketch` -- THE one entry into a sketch session.
 *
 * `create` mints the sketch node (through CommandHistory, so it appears in the tree and Ctrl+Z takes
 * it back out); `reopen` binds an existing one. Both then run the identical mount, so a re-entered
 * sketch and a fresh one cannot behave differently.
 */
type PackageSketchEntry =
  | {
      mode: 'create'
      /** Raw sketch id (`SKn`); the node id is `sketch3dNodeId(rawSketchId)`. */
      rawSketchId: string
      planeNodeId: string
      frame: PlaneFrame
      /** Owning Layer2D name. Display-only here; the workbench has no 2D layer panel. */
      layerId: string
      /** Legacy compatibility seed. Fresh face entry deliberately passes neither this nor refs. */
      seed?: FaceSketchSeed
      externalRefs?: Sketch3dExternalRef[]
      sizeHintMm?: number
      /**
       * Whether creating the node goes through `CommandHistory` (one Ctrl+Z takes the sketch back
       * out) or is inserted directly.
       *
       * THIS ASYMMETRY IS INHERITED, NOT INVENTED, and SKC-15C preserves it deliberately rather than
       * silently changing user-facing undo behavior inside a severing WO:
       *
       *   free sketch (base plane)  TRUE.  SKC-15B's `beginPackageSketch` created the node through
       *                                    `history.execute(createFeatureCommand(...))`.
       *   sketch on face            FALSE. SKC-5's entry called `commitSketch3dDocument`, which
       *                                    inserts straight into the DAG. Its own comment states the
       *                                    intent: "the fresh sketch-on-face ENTRY path ... is
       *                                    INTENTIONALLY not undo-tracked (creating the node at all
       *                                    isn't a per-gesture edit)". `SolidsWorkbenchPage.sketchOnFaceDegrade.test.tsx`
       *                                    depends on it: it presses Undo ONCE and expects the
       *                                    EXTRUDE to disappear.
       *
       * WO UI-16 (Q-14, Operator-answered 2026-07-10, choice=composite): the honest end state SKC-15C's
       * comment above predicted is now built. A face entry sets `undoable: true` AND `datumInput`
       * (the freshly-built, not-yet-inserted datum node -- see handleCanvasClick), and beginPackageSketch
       * below bundles [createFeatureCommand(datumInput), createFeatureCommand(sketch input)] into ONE
       * CompositeCommand. Ctrl+Z now removes both together; no intermediate orphan-plane state is
       * reachable via undo. The plain (non-face) base-plane entry (beginBasePlaneSketch) never sets
       * `datumInput` -- its own undo granularity (one sketch node, no datum) is UNCHANGED.
       */
      undoable: boolean
      /** WO UI-16 (Q-14): set ONLY by the fresh (non-reattach) sketch-on-face entry -- the freshly
       *  built (not-yet-inserted) face-plane datum node this sketch's plane belongs to. Present ⇒
       *  `undoable` must be true, and beginPackageSketch bundles this datum's own createFeatureCommand
       *  with the sketch's into ONE CompositeCommand instead of inserting the sketch alone. */
      datumInput?: DagNodeInput
    }
  | { mode: 'reopen'; sketchNodeId: string; planeNodeId: string; frame: PlaneFrame; sizeHintMm?: number }

type PackageSketchEntrySnapshot = {
  nodeId: string
  created: boolean
  originalSketch: CamSketch
  history: CommandHistoryCheckpoint
  datumNodeId?: string
}

/**
 * Charter item 3, applied to the plane itself. A `PlaneFrame` whose normal or xDir carries a NaN (a
 * degenerate face, a datum whose regen failed halfway) places every sketch coordinate derived from
 * it at NaN -- and `NaN > tol` is false in BOTH directions, so no snap guard, no picking tolerance
 * and no profile validator downstream would ever object. A zero-length normal is the same failure
 * with finite numbers. Both are refused HERE, at the accept point, before a session opens.
 */
function isFinitePlaneFrame(frame: PlaneFrame | undefined): frame is PlaneFrame {
  if (frame === undefined) return false
  const vs = [frame.origin, frame.normal, frame.xDir]
  for (const v of vs) {
    if (v === undefined || v === null) return false
    if (!Number.isFinite(v.x) || !Number.isFinite(v.y) || !Number.isFinite(v.z)) return false
  }
  const nLen = Math.hypot(frame.normal.x, frame.normal.y, frame.normal.z)
  const xLen = Math.hypot(frame.xDir.x, frame.xDir.y, frame.xDir.z)
  return nLen > 1e-9 && xLen > 1e-9
}

/** Resolve a tree datum to the plain plane contract consumed by extrude.
 * A retained frame belongs to display/repair only after current replay fails;
 * requiring status here keeps persisted payloads from bypassing picker UX. */
function extrudePlaneDef(dag: FeatureDag, nodeId: string, status: FeatureStatus): PlaneDef | undefined {
  const base = basePlaneFrame(nodeId)
  if (isFinitePlaneFrame(base)) return { origin: base.origin, normal: base.normal, xDir: base.xDir }
  const node = dag.getNode(nodeId)
  if (node?.degraded === true || isUnresolvedPlaneStatus(status)) return undefined
  const payload = node !== undefined && isOffsetPlaneDatumPayload(node.payload) ? node.payload : undefined
  return payload !== undefined && isFinitePlaneFrame(payload.lastGoodFrame)
    ? { origin: payload.lastGoodFrame.origin, normal: payload.lastGoodFrame.normal, xDir: payload.lastGoodFrame.xDir }
    : undefined
}

/** Convert the bridge's transient adjacent-edge vertex token into the stable
 * adjacent-FACE-set id the document/kernel contract requires. Malformed seam
 * or orphan edges fail closed instead of becoming a persisted pseudo-id. */
function stableVertexIdFromEdges(edgeIds: readonly StableId[]): StableId | undefined {
  const faces = new Set<StableId>()
  for (const edgeId of edgeIds) {
    const parsed = parseStableId(edgeId)
    if (parsed.kind !== 'edge' || parsed.operands.length !== 2) return undefined
    if (parsed.operands.some((operand) => operand.isSeam || operand.isOrphan)) return undefined
    for (const operand of parsed.operands) faces.add(operand.raw)
  }
  return faces.size >= 2 ? vertexId([...faces]) : undefined
}

/** Offset-plane hover feedback must fail closed before the async datum probe:
 *  only a snapshot that can form a finite planar frame may look clickable. */
function isEligibleOffsetPlaneFaceSnapshot(snapshot: ElementGeometrySnapshot | undefined): boolean {
  if (snapshot?.surfaceType !== 'plane' || snapshot.normal === undefined) return false
  const vectors = [snapshot.centroid, snapshot.normal]
  if (vectors.some((vector) => !Number.isFinite(vector.x) || !Number.isFinite(vector.y) || !Number.isFinite(vector.z))) return false
  return Math.hypot(snapshot.normal.x, snapshot.normal.y, snapshot.normal.z) > 1e-9
}

/** A retained last-good frame is display/repair state, not authority to start
 * a new sketch after the datum's current replay failed. */
function isUnresolvedPlaneStatus(status: FeatureStatus): boolean {
  return status === 'failed' || status === 'degraded'
}

/** WO SKC-15C-R1 (M3): exact component equality of two plane frames. Used by `recomputeSketchProfile`
 *  to detect that the plane MOVED across its extract await -- a profile computed against a frame the
 *  plane has since left would place a real body in the wrong spot with nothing red. Exact (not
 *  tolerant): the frame object is recomputed from the same datum each pass, so an unchanged plane
 *  yields bit-identical components, and any genuine move is a different number. */
function framesEqual(a: PlaneFrame, b: PlaneFrame): boolean {
  const eq = (u: { x: number; y: number; z: number }, v: { x: number; y: number; z: number }): boolean =>
    u.x === v.x && u.y === v.y && u.z === v.z
  return eq(a.origin, b.origin) && eq(a.normal, b.normal) && eq(a.xDir, b.xDir)
}

// Finished sketches must remain readable when the user explicitly turns the
// eye back on over the default blue model. Native geometry uses a cool mint;
// Project/Use references use the same violet semantic as the live SketchLayer.
const FINISHED_SKETCH_COLOR = 0x32e6a1
const FINISHED_SKETCH_UNDERLAY_COLOR = 0x071820
const FINISHED_SKETCH_UNDERLAY_WIDTH_PX = 3.25
const PROJECTED_SKETCH_COLOR = 0xd58cff
const PROFILE_PICK_HOVER_COLOR = 0xffd27a
const PROFILE_PICK_SELECTED_COLOR = 0xffa500
const PROFILE_PICK_RENDER_ORDER = 35
const FINISHED_SKETCH_DASH_PX = 6
const FINISHED_SKETCH_GAP_PX = 4
// Q-77 (Operator ruling 2026-07-26): a finished sketch outline coincident with a world axis or the
// coplanar base plane must render ON TOP of that furniture, never lose the equal-depth tie to it.
// The genesis glyphs (world axes, datum planes, plane labels) paint at renderOrder 1..2
// (genesisGlyphs.ts AMBIENT_RENDER_ORDER=1, label=1.5, EMPHASIS_RENDER_ORDER=2); a higher order plus
// depthTest/Write off makes the outline draw last and unconditionally, so an on-axis edge stays
// visible at the isometric landing camera. The at-rest outline stays below
// body hover/selection feedback (19+) and the live sketch layer (30), while
// remaining above world furniture (1..2).
const FINISHED_SKETCH_RENDER_ORDER = 10
// Q-77 (Operator's complement idea): a sketch edge lying exactly on a world axis gets a SUBTLY different
// tint signalling that relationship, mirroring how a constraint-based sketcher recolours a
// constrained/defined entity. We blend the sketch blue toward the app's own fully-defined
// (constrained) colour so the treatment reads as "locked to the axis" without being loud.
const ON_AXIS_SKETCH_TINT = 0.5
// A world-tolerance for "point sits on a world axis" (promoted geometry lands on exact integers/zeros).
const ON_AXIS_TOL_MM = 1e-4

/** True when the segment a->b lies along a world axis (X, Y, or Z) -- both endpoints share the two
 *  zero coordinates of that axis. This is the honest, view-independent signal for the visual overlap
 *  Operator flagged: an edge drawn on top of an axis reads as the axis unless it is tinted. */
function segmentOnWorldAxis(
  a: { x: number; y: number; z: number },
  b: { x: number; y: number; z: number },
): boolean {
  const near = (v: number): boolean => Math.abs(v) < ON_AXIS_TOL_MM
  const onX = near(a.y) && near(a.z) && near(b.y) && near(b.z)
  const onY = near(a.x) && near(a.z) && near(b.x) && near(b.z)
  const onZ = near(a.x) && near(a.y) && near(b.x) && near(b.y)
  return onX || onY || onZ
}

function paintFinishedSketchProfilePick(line: THREE.Line, color: number | null): void {
  const materials = Array.isArray(line.material) ? line.material : [line.material]
  for (const material of materials) {
    const colored = material as THREE.Material & { color?: THREE.Color }
    if (colored.color === undefined) continue
    const stored = colored.userData.profilePickBaseColor
    if (typeof stored !== 'number') colored.userData.profilePickBaseColor = colored.color.getHex()
    colored.color.setHex(color ?? (colored.userData.profilePickBaseColor as number))
    colored.needsUpdate = true
  }
}

/**
 * A dark screen-space underlay makes the one-pixel semantic stroke readable
 * against a light model face without sacrificing its bright contrast against
 * the dark canvas. It uses the same world coordinates as the sketch: no Z
 * offset, polygon offset, or camera-facing displacement is allowed here.
 */
function addFinishedSketchContrastUnderlay(
  line: THREE.Line,
  pairedPoints: readonly THREE.Vector3[],
): void {
  if (pairedPoints.length < 2) return
  const geometry = new LineSegmentsGeometry()
  geometry.setPositions(pairedPoints.flatMap((point) => [point.x, point.y, point.z]))
  const material = new LineMaterial({
    color: FINISHED_SKETCH_UNDERLAY_COLOR,
    linewidth: FINISHED_SKETCH_UNDERLAY_WIDTH_PX,
    worldUnits: false,
    transparent: true,
    opacity: 0.96,
    depthTest: false,
    depthWrite: false,
    toneMapped: false,
  })
  const underlay = new LineSegments2(geometry, material)
  underlay.userData.finishedSketchContrastUnderlay = true
  underlay.renderOrder = FINISHED_SKETCH_RENDER_ORDER - 0.25
  underlay.frustumCulled = false
  const resolution = new THREE.Vector2()
  underlay.onBeforeRender = (renderer) => {
    material.resolution.copy(renderer.getDrawingBufferSize(resolution))
  }
  line.add(underlay)
}

/**
 * Build the one cached scene object for a finished sketch while preserving the material split between
 * profile and construction geometry. The geometry groups are deliberately ordered normal, then
 * construction; tests read those groups from the real scene object so a future aggregate-solid
 * regression cannot pass by checking only the document flag.
 *
 * LineDashedMaterial measures dashSize/gapSize against lineDistance * scale. Recompute scale immediately
 * before every render so the 6px/4px recipe remains screen-stable as the finished model is orbited or
 * zoomed, matching the live sketch layer rather than freezing a world-mm pattern at Finish time.
 */
function makeFinishedSketchOutline(
  normalPoints: THREE.Vector3[],
  constructionPoints: THREE.Vector3[],
  planeOrigin: { x: number; y: number; z: number },
  axisAlignedPoints: THREE.Vector3[] = [],
  projectedPoints: THREE.Vector3[] = [],
  projectedConstructionPoints: THREE.Vector3[] = [],
): THREE.LineSegments | null {
  if (
    normalPoints.length === 0 &&
    constructionPoints.length === 0 &&
    axisAlignedPoints.length === 0 &&
    projectedPoints.length === 0 &&
    projectedConstructionPoints.length === 0
  ) return null

  // Material index convention: 0 = native, 1 = native construction, 2 = on-axis (Q-77),
  // 3 = Project/Use reference, 4 = Project/Use construction reference.
  const MI_NORMAL = 0, MI_CONSTRUCTION = 1, MI_ON_AXIS = 2, MI_PROJECTED = 3, MI_PROJECTED_CONSTRUCTION = 4
  const geometry = new THREE.BufferGeometry().setFromPoints([
    ...normalPoints,
    ...axisAlignedPoints,
    ...constructionPoints,
    ...projectedPoints,
    ...projectedConstructionPoints,
  ])
  let cursor = 0
  if (normalPoints.length > 0) { geometry.addGroup(cursor, normalPoints.length, MI_NORMAL); cursor += normalPoints.length }
  if (axisAlignedPoints.length > 0) { geometry.addGroup(cursor, axisAlignedPoints.length, MI_ON_AXIS); cursor += axisAlignedPoints.length }
  if (constructionPoints.length > 0) { geometry.addGroup(cursor, constructionPoints.length, MI_CONSTRUCTION); cursor += constructionPoints.length }
  if (projectedPoints.length > 0) { geometry.addGroup(cursor, projectedPoints.length, MI_PROJECTED); cursor += projectedPoints.length }
  if (projectedConstructionPoints.length > 0) {
    geometry.addGroup(cursor, projectedConstructionPoints.length, MI_PROJECTED_CONSTRUCTION)
  }

  const normalMaterial = new THREE.LineBasicMaterial({ color: FINISHED_SKETCH_COLOR, toneMapped: false })
  const constructionColor = new THREE.Color(FINISHED_SKETCH_COLOR)
    .lerp(new THREE.Color(asNumber('--vp-canvas')), 0.2)
    .getHex()
  const constructionMaterial = new THREE.LineDashedMaterial({
    color: constructionColor,
    dashSize: FINISHED_SKETCH_DASH_PX,
    gapSize: FINISHED_SKETCH_GAP_PX,
    toneMapped: false,
  })
  // Q-77 complement: on-axis edges tinted toward the fully-defined/constrained colour (subtle).
  const onAxisColor = new THREE.Color(FINISHED_SKETCH_COLOR)
    .lerp(new THREE.Color(asNumber('--sketch-fully-defined')), ON_AXIS_SKETCH_TINT)
    .getHex()
  const onAxisMaterial = new THREE.LineBasicMaterial({ color: onAxisColor, toneMapped: false })
  const projectedMaterial = new THREE.LineBasicMaterial({ color: PROJECTED_SKETCH_COLOR, toneMapped: false })
  const projectedConstructionColor = new THREE.Color(PROJECTED_SKETCH_COLOR)
    .lerp(new THREE.Color(asNumber('--vp-canvas')), 0.35)
    .getHex()
  const projectedConstructionMaterial = new THREE.LineDashedMaterial({
    color: projectedConstructionColor,
    dashSize: FINISHED_SKETCH_DASH_PX,
    gapSize: FINISHED_SKETCH_GAP_PX,
    toneMapped: false,
  })
  // FINISHED FACE-SKETCH PRESENTATION CONTRACT:
  // - transparent=true with opacity 1 routes every material through Three's
  //   transparent pass, after the opaque modeled body regardless of camera side;
  // - depthTest/depthWrite off keeps an explicitly eye-on sketch visible even
  //   when its support face is on the far side of the body;
  // - frustum culling is disabled on the object below because a zero-thickness,
  //   coplanar line bound is a poor camera-side discriminator.
  //
  // The prior opaque renderOrder-only contract passed property tests yet failed
  // the real top-face SK3 raster: the body overpainted it from the support-face
  // side while the same geometry remained visible from below.
  const materials = [
    normalMaterial,
    constructionMaterial,
    onAxisMaterial,
    projectedMaterial,
    projectedConstructionMaterial,
  ]
  for (const m of materials) {
    m.transparent = true
    m.opacity = 1
    m.depthTest = false
    m.depthWrite = false
  }
  const line = new THREE.LineSegments(geometry, materials)
  line.renderOrder = FINISHED_SKETCH_RENDER_ORDER
  line.frustumCulled = false
  addFinishedSketchContrastUnderlay(line, [
    ...normalPoints,
    ...axisAlignedPoints,
    ...projectedPoints,
  ])
  line.computeLineDistances()
  line.onBeforeRender = (renderer, _scene, camera) => {
    const canvas = renderer.domElement
    const pixelHeight = canvas.clientHeight || canvas.height || 1
    let worldPerPixel = 1
    if (camera instanceof THREE.PerspectiveCamera) {
      const distance = camera.position.distanceTo(
        new THREE.Vector3(planeOrigin.x, planeOrigin.y, planeOrigin.z),
      )
      worldPerPixel = (2 * Math.tan((camera.fov * Math.PI) / 360) * distance) / pixelHeight
    } else if (camera instanceof THREE.OrthographicCamera) {
      worldPerPixel = (camera.top - camera.bottom) / Math.max(camera.zoom * pixelHeight, 1e-9)
    }
    const dashScale = 1 / Math.max(
      Number.isFinite(worldPerPixel) && worldPerPixel > 0 ? worldPerPixel : 1,
      1e-9,
    )
    constructionMaterial.scale = dashScale
    projectedConstructionMaterial.scale = dashScale
  }
  return line
}

/**
 * WO SKC-15C-R1 (M3), the injectable seam (charter bar 4: async staleness is settled by a COMMITTED
 * constructed interleave, never by event-loop prose). `recomputeSketchProfile` awaits `extractSketchProfile`
 * (a real geom2d init); a test needs to land a concurrent same-node commit DURING that await to prove
 * the stale-result guard refuses to publish a profile for a sketch the node has since replaced. This
 * gate is awaited inside the recompute exactly where that delay lives. Default: no-op (nothing awaits).
 */
let profileRecomputeGate: (() => Promise<void>) | null = null
export function __setProfileRecomputeGate(gate: (() => Promise<void>) | null): void {
  profileRecomputeGate = gate
}

/**
 * WO SKC-15C: representative local points of a CAM sketch, used ONLY to size the camera's
 * normal-to-plane framing on re-entry (`Math.max(|p|)` -> a radius). Deliberately coarse: an arc's
 * centre plus radius bounds it, a spline's control points bound it. Nothing downstream reads these
 * as geometry, so an approximation here can make the camera slightly wide but can never move a
 * vertex. Non-finite coordinates are dropped rather than propagated into the framing.
 */
function camSketchExtentSamples(sketch: CamSketch): Array<{ x: number; y: number }> {
  const out: Array<{ x: number; y: number }> = []
  const push = (x: number, y: number): void => {
    if (Number.isFinite(x) && Number.isFinite(y)) out.push({ x, y })
  }
  const bound = (e: CamSketchEntity): void => {
    switch (e.kind) {
      case 'point': push(e.at.x, e.at.y); break
      case 'line': push(e.start.x, e.start.y); push(e.end.x, e.end.y); break
      case 'circle':
      case 'arc':
        push(e.center.x + e.radius, e.center.y + e.radius)
        push(e.center.x - e.radius, e.center.y - e.radius)
        break
      case 'ellipse':
      case 'elliptical-arc': {
        const r = Math.max(e.majorRadius, e.minorRadius)
        push(e.center.x + r, e.center.y + r)
        push(e.center.x - r, e.center.y - r)
        break
      }
      case 'spline':
        for (const p of e.points) push(p.x, p.y)
        break
      case 'text':
        push(e.at.x, e.at.y)
        break
    }
  }
  for (const e of sketch.entities) bound(e)
  return out
}

/** WO UI-5: one entry of a body-producing feature node's accumulated
 *  push/pull history -- stored on `node.payload.faceEdits` (a plain array,
 *  same "the DAG node's own payload IS the state" contract BoxSizeDialog's
 *  size field and ExtrudeDialog's distance field already follow), never a
 *  separate DAG node. A push-pull edit isn't itself a new solid from a
 *  profile -- it re-shapes whichever feature owns the picked body -- so this
 *  rides the SAME EditFeaturePayloadCommand remove-then-reinsert-same-id
 *  undo machinery every other dialog Apply uses (see that command's own
 *  header comment), appended to on commit, replayed in order by the
 *  executor on every regen. */
type FaceEditPayload = Pick<FaceEditRequest, 'featureKey' | 'kind' | 'delta'>

/**
 * Every feature operation executes against one explicit replay world. The live
 * scheduler and the Push/Pull transaction's candidate scheduler both use the
 * same executor factory; only the world's storage/presentation policy differs.
 */
interface ReplayWorld {
  dag: FeatureDag
  map: ElementMap
  scheduler: RegenScheduler
  /** Scratch extrude previews must resolve datum targets against the live
   * scheduler: a fresh candidate scheduler cannot know that a retained frame
   * belongs to a currently failed/degraded plane. Live replay uses its world. */
  lookupExtrudePlaneTarget?: (nodeId: string) => PlaneDef | undefined
  bodyHandles: Map<string, BodyHandle>
  setFeatureVisible(featureId: string, visible: boolean): void
  disposePriorReplayHandle(featureId: string): Promise<void>
  disposeHandle(handle: BodyHandle): Promise<void>
  ownHandle(handle: BodyHandle): void
  inheritBodyAppearance(node: DagNodeSnapshot): void
  publishBody(featureId: string, handle: BodyHandle): Promise<void>
  migrateFaceIds(delta: NonNullable<OpResult['elementMap']>): void
  recomputeSketchProfile(nodeId: string): Promise<Diag[]>
}

/** WO UI-5: the toolbar "Push/Pull" toggle's own in-viewport interaction
 *  state, parallel to `SketchMode` above (a different in-viewport,
 *  click-to-pick + drag interaction, never a dialog):
 *   - 'arm'     : toolbar toggle is on, waiting for a supported face click.
 *   - 'mounted' : a supported face was picked; the gizmo is attached
 *                 and a drag may be in progress. `baseHandle` is the body's
 *                 CURRENT COMMITTED kernel handle (pre-this-gesture) that
 *                 every preview call re-derives from -- never mutated by a
 *                 preview itself (mission #2's "preview never enters command
 *                 history" -- see handlePushPullPreview). */
/** WO UI-14A-R3 (UI-14A-R2.audit.json blocker): the IDENTITY of one mounted
 *  push/pull gesture. Minted by handlePushPullPick, carried ON the 'mounted'
 *  mode object itself -- so every closure that can end it (the gizmo's own
 *  onChange, the shared AnchoredValueEntry's Apply/Cancel callbacks -- WO
 *  UI-79 F-A removed the gizmo's onCommit seam entirely -- the Escape keydown
 *  effect) automatically captures the token
 *  of the gesture it was built for, with no extra plumbing. Retired (the live
 *  ref set to null) in the gesture end's `finally`, which is what makes "is the
 *  gesture that is asking still the LIVE one?" answerable SYNCHRONOUSLY, from
 *  any callback, at any point in React's cleanup tail. See
 *  pushPullActiveGestureRef for the full tail enumeration. */
type PushPullGesture = { readonly id: number }

type PushPullMode =
  | { kind: 'none' }
  | { kind: 'arm' }
  | {
      kind: 'mounted'
      gesture: PushPullGesture
      /** Upstream body used as the kernel input for every preview. */
      ownerId: string
      /** Current live body whose visible mesh the transient preview replaces.
       *  For edit mode this is derived from the replayed DAG lineage, so a
       *  downstream body-producing feature is targeted instead of the hidden
       *  push/pull node it consumes. */
      previewFeatureId: string
      faceId: string
      frame: FaceFrame
      baseHandle: BodyHandle
      /** Committed presentation body restored by Cancel/Escape. */
      restoreHandle: BodyHandle
      /** Exact committed cache/BVH/geometry presentation retained while preview replaces it. */
      presentation: RetainedCachedBody
      /** Exact committed visibility-collapse source restored with the presentation. */
      pristine: PristineGeometrySnapshot | undefined
      /** Existing push/pull node for edit mode; null for a new feature. */
      editFeatureId: string | null
    }

/** The 'mounted' variant, named -- the ONE shape the gizmo's live seams
 *  (runPushPullPreview, handlePushPullCommit) accept. Carrying the full
 *  variant (rather than a structural {ownerId,faceId,baseHandle}) is what puts
 *  `gesture` in their hands. */
type PushPullMounted = Extract<PushPullMode, { kind: 'mounted' }>

/** WO UI-14A-R3 (UI-14A-R2.audit.json finding 3): the EXCEPTION policy for a
 *  gesture end. Both handlers are `void`-called from a gizmo/DOM seam, so a
 *  re-thrown kernel failure would surface only as an unhandled rejection; and
 *  because the R3 token is retired in the `finally`, a handler that threw
 *  before its own `setPushPullMode({kind:'none'})` would leave a gizmo mounted
 *  whose every seam (preview, commit, cancel) now refuses -- a wedged, silently
 *  inert gizmo, strictly worse than the wedged lock the R2 `finally` was added
 *  to prevent. So a throwing gesture end drops to idle and surfaces the reason
 *  through the same pushPullRefusal hint every other refusal uses ("never a
 *  silent no-op"). Bound by the exception-path test in
 *  SolidsWorkbenchPage.pushPull.test.tsx. */
function pushPullGestureFailureReason(err: unknown): string {
  const detail = err instanceof Error ? err.message : String(err)
  return workbenchText('SolidsWorkbenchPage.pushPullCouldNotFinishTheGestureWasDiscarded', { detail: String(detail) })
}

