/**
 * Record a command whose document mutation already crossed a serialized
 * adoption boundary. CommandHistory.execute() normally applies before it
 * records, so the first do() must be swallowed; later redo() calls delegate
 * normally. This keeps the Chamfer history action invisible until its async
 * handle disposal/downstream replay has finished without losing ordinary
 * undo/redo semantics afterward.
 */
function alreadyAppliedHistoryCommand(command: Command): Command {
  let skipInitialDo = true
  return {
    label: command.label,
    do: (dag) => {
      if (skipInitialDo) {
        skipInitialDo = false
        return
      }
      command.do(dag)
    },
    undo: (dag) => command.undo(dag),
    serialize: () => command.serialize(),
  }
}

