  const offsetPlanePreviewIntentRef = useRef<OffsetPlaneDialogValue | null>(null)
  const offsetPlanePreviewPageGenerationRef = useRef(0)
  const offsetPlanePreviewGhostRef = useRef<THREE.Object3D | null>(null)
  const [offsetPlanePreviewState, setOffsetPlanePreviewState] = useState<OffsetPlanePreviewState>({ status: 'idle' })

