  const revolveAxisHighlightRef = useRef<THREE.Line | null>(null)

  // WO-042: Hole on the shared session (see HolePreviewBaseline's doc).
  const holePreviewSessionRef = useRef<FeaturePreviewSession<
    HolePreviewBaseline,
    HolePreviewIntent,
    BodyHandle,
    HolePreviewCandidate
